pub(crate) fn close(&self) {
    self.closed.cancel();
    // A poisoned guard cannot authorize anything. Its retained socket
    // aliases are still owned here and must be shut down to wake waiters.
    let streams = {
        let mut state = match self.state.lock() {
            Ok(state) => state,
            Err(poisoned) => poisoned.into_inner(),
        };
        state.closed = true;
        state.epoch = state.epoch.saturating_add(1);
        std::mem::take(&mut state.streams)
    };
    self.changed.notify_all();
    for stream in streams.into_values() {
        stream.shutdown();
    }
}

pub(crate) fn original_retirement_custody(&self) -> OriginalRequiredPurposeRetirement {
    OriginalRequiredPurposeRetirement {
        gate: Arc::clone(&self.closing.gate),
        id: self._stream.id,
        retired: Arc::clone(&self.retired),
    }
}

pub(crate) fn shutdown_original_after_root_intent(
    &self,
    intent: &crate::same_actor_q24_deployment::OriginalRootRetirementIntent,
) -> Result<(), crate::AgentdError> {
    self.original_retirement_custody().shutdown_original_after_root_intent(intent)
}

pub(crate) fn finish_original_after_root_exit(
    mut self,
    exited: &crate::same_actor_q24_deployment::OriginalRootProcessExited,
    identity: &crate::AgentdIdentity,
) -> Result<(), crate::AgentdError> {
    exited.require_original_cleanup_origin(identity, &self.gate)?;
    self.gate.close();
    let worker = self.worker.take().ok_or_else(|| {
        crate::AgentdError::GenerationFenced("actual deadline watcher was already consumed".into())
    })?;
    worker.join().map_err(|_| {
        crate::AgentdError::GenerationFenced("actual deadline watcher panicked".into())
    })?;
    exited.require_original_cleanup_origin(identity, &self.gate)
}

pub(crate) fn shutdown_original_after_root_intent(
    &self,
    intent: &crate::same_actor_q24_deployment::OriginalRootRetirementIntent,
) -> Result<(), crate::AgentdError> {
    let checked = (|| {
        intent.require_original_gate(&self.gate)?;
        if self.retired.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return Err(refused("original purpose retirement was already consumed").into());
        }
        {
            let mut state = self.gate.state.lock()
                .map_err(|_| refused("original purpose Gate is poisoned"))?;
            self.gate.check_locked(&mut state)?;
            let Some(OriginalPhaseEndpoint::Stream(stream)) = state.streams.get(&self.id) else {
                return Err(refused("original purpose stream registration is unavailable").into());
            };
            // The registered alias is a clone of the actual owner's
            // socket. shutdown affects that same socket and every clone;
            // merely dropping one FD would leave the peer alive.
            stream.shutdown(Shutdown::Both)?;
            self.gate.check_locked(&mut state)?;
        }
        intent.require_original_gate(&self.gate)?;
        Ok::<(), crate::AgentdError>(())
    })();
    if checked.is_err() {
        self.gate.close();
    }
    checked
}

pub(crate) fn require_original_origin(
    &self, identity: &AgentdIdentity, gate: &Arc<SameActorPhaseGate>,
) -> Result<(), AgentdError> {
    if self.context.identity() != identity || !Arc::ptr_eq(self.context.gate(), gate)
        || self.attachment.is_none() || self.device.is_none() || self.mcp.is_none()
    {
        self.context.gate().close();
        return Err(runtime_refused("actual stopped Runtime custody differs"));
    }
    self.app_server_joined.require_original_custody(&self.app_server)
        .map_err(|error| AgentdError::Protocol(format!("original App Server join: {error}")))?;
    self.context.gate().require_open()?;
    crate::root_observation_stream::check_lifetime(&self.root_pidfd)
        .map_err(|error| AgentdError::Protocol(format!("original stopped Root lifetime: {error}")))
}

pub(crate) fn stop_and_join_original(&mut self) -> Result<(), AgentdError> {
    self.context.gate().close();
    let thread = self.thread.take()
        .ok_or_else(|| deployment_refused("original coordinator result already consumed"))?;
    join_original_thread(thread).map(drop)
}

pub(super) fn open_original_c_task(
    &self,
    files: &mut OriginalDeploymentFiles,
    now: u64,
) -> Result<OriginalCellQ24TaskLedgerInputsV1, AgentdError> {
    self.open_original_task(&self.data.original_c, files, now)
}

pub(super) fn open_original(
    &self,
    files: &mut OriginalDeploymentFiles,
) -> Result<FileAnchorWitnessStore, AgentdError> {
    let scope = JournalScope {
        scope_digest: Digest32::from_array(self.scope),
        objective_digest: Digest32::from_array(self.objective),
    };
    let generation = Generation::new(self.generation).map_err(deployment_error)?;
    let file = files.open_original_owner(&self.file)?;
    files.require_original_context()?;
    let witness = FileAnchorWitnessStore::open(
        file, scope, generation, self.maximum_records,
    )
    .map_err(deployment_error)?;
    files.require_original_context()?;
    Ok(witness)
}

pub(super) fn open_original(
    &self,
    files: &mut OriginalDeploymentFiles,
) -> Result<(Arc<LoadedCellQ24ModelV1>, CellCompatibilityBundleV1), AgentdError> {
    files.require_original_context()?;
    let base = files.read_original(&self.base, 16 * 1024 * 1024)?;
    let encoder = files.read_original(&self.encoder, 16 * 1024 * 1024)?;
    let heads = files.read_original(&self.heads, 16 * 1024 * 1024)?;
    let organ = self.organ_adapter.as_ref()
        .map(|file| files.read_original(file, 16 * 1024 * 1024)).transpose()?;
    let cell = self.cell_adapter.as_ref()
        .map(|file| files.read_original(file, 16 * 1024 * 1024)).transpose()?;
    let model = LoadedCellQ24ModelV1::open_files(CellQ24ModelFilesV1 {
        base: base.clone_original_file()?,
        encoder: encoder.clone_original_file()?,
        heads: heads.clone_original_file()?,
        organ_adapter: organ.as_ref().map(|read| read.clone_original_file()).transpose()?,
        cell_adapter: cell.as_ref().map(|read| read.clone_original_file()).transpose()?,
    }).map_err(deployment_error)?;
    for read in [&base, &encoder, &heads].into_iter().chain(organ.iter()).chain(cell.iter()) {
        read.require_original_pin()?;
    }
    let bundle = self.bundle.original()?;
    bundle.digest().map_err(deployment_error)?;
    if model.components() != &bundle.components {
        return Err(deployment_refused("actual model components differ from the approved bundle"));
    }
    files.require_original_context()?;
    Ok((Arc::new(model), bundle))
}

pub(super) fn reopen_original(
    self, files: &mut OriginalDeploymentFiles,
) -> Result<crate::AgentdGenerationUpdatePredecessorFilesV1<codex_hepta_neuron::FileAnchorWitnessStore>, AgentdError> {
    let journal = self.journal.reopen_original(files)?;
    let witness_file = self.witness.reopen_original(files)?;
    files.require_original_context()?;
    let witness = codex_hepta_neuron::FileAnchorWitnessStore::open(
        witness_file, self.config.witness_scope, self.config.witness_generation, self.config.witness_records,
    ).map_err(deployment_error)?;
    files.require_original_context()?;
    Ok(crate::AgentdGenerationUpdatePredecessorFilesV1 {
        file: journal, witness, config: self.config.generation, max_records: self.config.journal_records,
    })
}

pub(crate) fn retain_original_bootstrap_consumer_handle(
    mut self, handle: JoinHandle<Result<FinalUseAuthority, AgentdError>>,
) -> Arc<OriginalBootstrapConsumerJob> {
    let job = Arc::new(OriginalBootstrapConsumerJob {
        state: tokio::sync::Mutex::new(ConsumerJobState {
            handle: Some(handle), output: None, joined: false, receiving: false,
        }),
        gate: Arc::clone(&self.gate),
    });
    self.state.jobs.push(Arc::clone(&job));
    self.armed = false;
    job
}

pub(crate) fn receive_original(
    self: &Arc<Self>,
) -> impl Future<Output = Result<FinalUseAuthority, AgentdError>> + Send + 'static {
    let job = Arc::clone(self);
    let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
    async move {
        let mut state = job.state.lock().await;
        if state.receiving {
            return Err(refused("original bootstrap consumer result was already received"));
        }
        state.receiving = true;
        job.join_locked(&mut state).await;
        let output = state.output.take()
            .ok_or_else(|| refused("original bootstrap consumer output missing"))?;
        let owner = output?;
        job.gate.require_open()?;
        closing.disarm();
        Ok(owner)
    }
}
